INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Pseudocode immer an eine bestimmte Programmiersprache gebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Unabhängig von Syntax"}, {"text": "Ja", "correct": false, "because": "Allgemeine Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Pseudocode?', 3, '[{"text": "Algorithmus verständlich darstellen", "correct": true, "because": "Fokussiert auf Logik"}, {"text": "Direkte Ausführung", "correct": false, "because": "Nicht ausführbar"}, {"text": "Manuelle Optimierung", "correct": false, "because": "Planungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente enthält Pseudocode typischerweise?', 5, '[{"text": "Schleifen", "correct": true, "because": "Darstellen Wiederholungen"}, {"text": "Bedingungen", "correct": true, "because": "Zeigen Entscheidungen"}, {"text": "Grafikdesigns", "correct": false, "because": "Irrelevant"}, {"text": "Musikwiedergabe", "correct": false, "because": "Nicht algorithmisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pseudocode ist sprachunabhängig. b) Er ist direkt kompilierbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht ausführbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung von Pseudocode?', 4, '[{"text": "Logische Struktur", "correct": false, "because": "Kern der Darstellung"}, {"text": "Klarheit", "correct": false, "because": "Fördert Verständnis"}, {"text": "Programmiersyntax", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Pseudocode für Anfänger geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Vereinfacht Algorithmusverständnis"}, {"text": "Nein", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat Pseudocode in der Entwicklung?', 3, '[{"text": "Planung von Algorithmen", "correct": true, "because": "Skizziert Logik vor Coding"}, {"text": "Direkte Ausführung", "correct": false, "because": "Nicht kompilierbar"}, {"text": "Manuelle Debugging", "correct": false, "because": "Planung, nicht Debugging"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Pseudocode?', 5, '[{"text": "Sprachunabhängigkeit", "correct": true, "because": "Kein Syntaxzwang"}, {"text": "Einfaches Verständnis", "correct": true, "because": "Fokussiert auf Logik"}, {"text": "Direkte Ausführung", "correct": false, "because": "Nicht möglich"}, {"text": "Hohe Komplexität", "correct": false, "because": "Vereinfacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Pseudocode hilft bei der Planung. b) Er ist nur für Profis. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch für Anfänger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Pseudocode?', 4, '[{"text": "Logische Abfolge", "correct": false, "because": "Kern der Darstellung"}, {"text": "Klarheit", "correct": false, "because": "Fördert Verständnis"}, {"text": "Programmiersprache", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Pseudocode ein ausführbares Programm?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Planungstool"}, {"text": "Ja", "correct": false, "because": "Nicht kompilierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen sind in Pseudocode üblich?', 4, '[{"text": "Bedingungen", "correct": true, "because": "Zeigen Entscheidungen"}, {"text": "Schleifen", "correct": true, "because": "Darstellen Wiederholungen"}, {"text": "3D-Modelle", "correct": false, "because": "Nicht algorithmisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Pseudocode immer kompliziert ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Vereinfacht Logik"}, {"text": "Ja", "correct": false, "because": "Klarheit zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erstellung von Pseudocode?', 3, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Maximale Details", "correct": false, "because": "Vereinfachung wichtiger"}, {"text": "Manuelle Syntax", "correct": false, "because": "Sprachunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pseudocode skizziert Algorithmen. b) Er ersetzt Programmiersprachen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) dient Planung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hilfsmittel unterstützen Pseudocode?', 5, '[{"text": "Flussdiagramme", "correct": true, "because": "Visualisieren Ablauf"}, {"text": "Texteditoren", "correct": true, "because": "Zum Schreiben geeignet"}, {"text": "Musiksoftware", "correct": false, "because": "Irrelevant"}, {"text": "Bildbearbeitung", "correct": false, "because": "Nicht algorithmisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Pseudocode unwichtig?', 3, '[{"text": "Logik", "correct": false, "because": "Kern der Darstellung"}, {"text": "Lesbarkeit", "correct": false, "because": "Fördert Verständnis"}, {"text": "Farbcodierung", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Pseudocode für Teamarbeit geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert gemeinsames Verständnis"}, {"text": "Nein", "correct": false, "because": "Kollaborativ nutzbar"}]'),
